package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	sum, count, largest := 0, 0, 0
	for scanner.Scan() {
		n, err := strconv.Atoi(scanner.Text())
		if err != nil {
			continue
		}
		if count == 0 || n > largest {
			largest = n
		}
		sum += n
		count++
	}
	if count == 0 {
		fmt.Println("No numbers")
		return
	}
	fmt.Printf("Sum: %d\nLargest: %d\n", sum, largest)
}

// Package grades turns marks out of 100 into letter grades.
package grades

// Letter is A for 80+, B for 70+, C for 60+, D for 50+, otherwise F.
func Letter(mark int) string {
	switch {
	case mark >= 80:
		return "A"
	case mark >= 70:
		return "B"
	case mark >= 60:
		return "C"
	case mark >= 50:
		return "D"
	default:
		return "F"
