    let numbers: Vec<f64> = input.split_whitespace().filter_map(|w| w.parse().ok()).collect();
    if numbers.is_empty() {
        println!("No numbers");
        return;
    }
    let sum: f64 = numbers.iter().sum();
    println!("Count: {}", numbers.len());
    println!("Average: {:.2}", sum / numbers.len() as f64);
}

